import zipfile
import xml.etree.ElementTree as ET
import sys

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}
M = NS["m"]


def col_to_idx(ref):
    letters = "".join(ch for ch in ref if ch.isalpha())
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch.upper()) - 64)
    return idx - 1


def parse_sheet(path, sheet_name, shared_strings):
    root = ET.parse(path).getroot()
    rows = {}
    for row in root.findall(f"{M}sheetData/{M}row"):
        rnum = int(row.get("r"))
        cells = {}
        for c in row.findall(f"{M}c"):
            ref = c.get("r")
            t = c.get("t")
            v_el = c.find(f"{M}v")
            is_el = c.find(f"{M}is")
            f_el = c.find(f"{M}f")
            if t == "s" and v_el is not None:
                val = shared_strings[int(v_el.text)]
            elif t == "inlineStr" and is_el is not None:
                val = "".join(x.text or "" for x in is_el.iter(f"{M}t"))
            elif v_el is not None:
                val = v_el.text
            else:
                val = None
            if f_el is not None:
                val = (val, "=" + (f_el.text or ""))
            cells[col_to_idx(ref)] = val
        rows[rnum - 1] = cells
    return rows


def main(path):
    zf = zipfile.ZipFile(path)
    names = zf.namelist()

    shared_strings = []
    if "xl/sharedStrings.xml" in names:
        sst = ET.fromstring(zf.read("xl/sharedStrings.xml"))
        for si in sst.findall(f"{M}si"):
            shared_strings.append("".join(x.text or "" for x in si.iter(f"{M}t")))

    # workbook sheet list
    wb = ET.fromstring(zf.read("xl/workbook.xml"))
    sheets = [(s.get("name"), s.get(f"{{{NS['r']}}}id")) for s in wb.findall(f"{M}sheets/{M}sheet")]
    rels = ET.fromstring(zf.read("xl/_rels/workbook.xml.rels"))
    rid_to_target = {r.get("Id"): r.get("Target") for r in rels}

    for name, rid in sheets:
        target = rid_to_target[rid]
        if not target.startswith("xl/"):
            target = "xl/" + target.lstrip("/")
        rows = parse_sheet(zf.open(target), name, shared_strings)
        print(f"=== Sheet: {name} (rows: {len(rows)}) ===")
        for rnum in sorted(rows):
            cells = rows[rnum]
            if cells:
                line = " | ".join(f"{rnum}:{cells[c]}" for c in sorted(cells))
                print(line)
        print()


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "budget.xlsx")

